"use client";

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import {
  UserCircle,
  Loader2,
  AlertCircle,
} from "lucide-react";
import { motion } from "framer-motion";
import Layout from "./Layout";

export default function AccountDeputydirector() {
  const [userData, setUserData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchUserData = async () => {
      const token = localStorage.getItem("token");
      const role = localStorage.getItem("role");

      if (!token || !role) {
        setError("Authentification requise. Veuillez vous connecter.");
        setIsLoading(false);
        navigate("/login");
        return;
      }

      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/auth/me`, {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: role,
          },
        });

        if (response.data.success) {
          setUserData(response.data.user);
        } else {
          setError(response.data.message || "Échec de la récupération des données.");
        }
      } catch (err) {
        setError(err.response?.data?.message || "Une erreur s'est produite. Veuillez réessayer.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchUserData();
  }, [navigate]);

  // Translate "Deputydirector" to "Gestionnaire d'hôtel"
  const getTranslatedRole = (role) => {
    return role === "Deputydirector" ? "Gestionnaire d'hôtel" : role;
  };

  const renderUserDetails = () => {
    if (!userData) return null;

    const commonFields = [
      { label: "Email", value: userData.email },
      { label: "Rôle", value: getTranslatedRole(userData.role) }, // Apply translation here
      { label: "Créé le", value: new Date(userData.createdAt).toLocaleDateString("fr-FR") },
    ];

    const specificFields = [
      { label: "Nom", value: userData.name },
      { label: "Numéro de téléphone", value: userData.phoneNumber || "Non spécifié" },
      { label: "Adresse", value: userData.address || "Non spécifié" },
      { label: "Date de naissance", value: userData.dateOfBirth ? new Date(userData.dateOfBirth).toLocaleDateString("fr-FR") : " reconocimientoNon spécifié" },
    ];

    const allFields = [...specificFields, ...commonFields];

    return (
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {allFields.map((field, index) => (
          <div key={index}>
            <p className="text-xs font-medium text-[#00717F] uppercase tracking-wider">{field.label}</p>
            <p className="text-sm text-#333333">{field.value || "Non spécifié"}</p>
          </div>
        ))}
      </div>
    );
  };

  return (
    <Layout>
      <div className="max-w-7xl mx-auto">
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="bg-white rounded-xl shadow-lg overflow-hidden border border-[#C8A45D/30]/50"
        >
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
              <div>
                <h1 className="text-2xl font-bold tracking-tight">Mon compte</h1>
                <p className="text-white/80 mt-1">Consultez vos informations personnelles</p>
              </div>
            </div>
          </div>

          <div className="p-6">
            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-8 w-8 text-[#00717F] animate-spin" />
                  <p className="text-gray-500">Chargement des données...</p>
                </div>
              </div>
            ) : error ? (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.3 }}
                className="p-4 bg-red-50 border-l-4 border-red-500 flex items-center gap-3 rounded-r-md shadow-sm"
              >
                <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
                <p className="text-red-700">{error}</p>
              </motion.div>
            ) : userData ? (
              <div className="space-y-8">
                <div className="flex items-center gap-4 border-b border-[#C8A45D/30]/50 pb-4">
                  <UserCircle className="h-12 w-12 text-[#00717F] opacity-80" />
                  <div>
                    <h2 className="text-xl font-semibold text-[#00717F]">{userData.name}</h2>
                    <p className="text-sm text-[#8B7355]">
                      Rôle: <span className="font-medium capitalize">{getTranslatedRole(userData.role)}</span>
                    </p>
                  </div>
                </div>

                {renderUserDetails()}

                <div className="flex flex-col sm:flex-row gap-4">
                  <motion.button
                    whileHover={{ scale: 1.05 }}
                    whileTap={{ scale: 0.95 }}
                    onClick={() => navigate("/DeputyDirectorDashboard")}
                    className="bg-[#00717F] text-white py-3 px-4 rounded-md shadow-sm hover:bg-[#00717F] transition-colors duration-300 flex items-center justify-center gap-2 text-sm font-medium"
                  >
                    Retour au tableau de bord
                  </motion.button>
                </div>
              </div>
            ) : (
              <div className="flex flex-col justify-center items-center h-64 text-gray-500">
                <UserCircle className="h-16 w-16 text-gray-300 mb-2" />
                <p className="mb-2">Aucune donnée disponible</p>
              </div>
            )}
          </div>
        </motion.div>
      </div>
    </Layout>
  );
}
